const store = $getWorkflowStaticData('global');
store.rt21 = { orders: [], invoices: [], orderLines: [], invoiceLines: [], sheetRanges: {}, fileId: null, sessionId: null };
const year = new Date().getFullYear();
return [{ json: {
  yearStart: year + '-01-01',
  driveId: 'b!GBMH8cf5mk2CZl1ZfpWgDMJRDzREsg1Npw0_haVaoSy_p0-rU6CqTIb8wOlQB4p-',
  folderId: '01ENPIF4CERGMSIGMKQVHKJW5HGYOOQVRD',
  templateName: 'RT21_template.xlsx',
  fileName: 'RT21 Orders and Invoices - Dashboard v4.xlsx'
} }];

const store = $getWorkflowStaticData('global').rt21;
const orders = $('Fetch Orders').first().json.value || [];
const invoices = $('Fetch Invoices').first().json.value || [];
store.orders = orders;
store.invoices = invoices;
const chunk = (arr, n) => { const out = []; for (let i = 0; i < arr.length; i += n) out.push(arr.slice(i, i + n)); return out; };
const esc = s => String(s).replace(/'/g, "''");
const items = [];
for (const c of chunk(orders.map(o => o.No), 80)) {
  items.push({ json: { kind: 'order', filter: "Document_Type eq 'Order' and (" + c.map(n => "Document_No eq '" + esc(n) + "'").join(' or ') + ")" } });
}
for (const c of chunk(invoices.map(v => v.No), 80)) {
  items.push({ json: { kind: 'invoice', filter: "(" + c.map(n => "Document_No eq '" + esc(n) + "'").join(' or ') + ")" } });
}
if (items.length === 0) items.push({ json: { kind: 'noop', filter: "Document_No eq 'NOOP_NONE'" } });
return items;

const store = $getWorkflowStaticData('global').rt21;
