const store = $getWorkflowStaticData('global').rt21;
const sheets = store.sheets; const old = store.old || {};
const colLetter = (n) => { let s=''; while(n>0){const m=(n-1)%26; s=String.fromCharCode(65+m)+s; n=Math.floor((n-1)/26);} return s; };
const driveId = store.__drive || $('Init').first().json.driveId;
const fileId = store.fileId; const sessionId = store.sessionId;
const CH=1000, ADDCH=500; const ops=[];
for (const s of sheets){
  const width=s.cols.length; const col=colLetter(width);
  const prop = s.useFormulas ? 'formulas' : 'values';
  const dataRows=s.rows.map(r=>s.cols.map(c=>{const v=r[c]; return (v===null||v===undefined)?'':v;}));
  const all = s.skipHeader ? dataRows : [s.cols, ...dataRows];
  const startRow = s.skipHeader ? 2 : 1;
  const newN=dataRows.length;
  const oldN=(s.sheet in old)?old[s.sheet]:-1;
  ops.push({ op:'ensureSheet', sheet:s.sheet, driveId, fileId, sessionId });
  if (oldN<0){
    for (let i=0;i<all.length;i+=CH){ const sl=all.slice(i,i+CH);
      ops.push({ op:'write', prop, sheet:s.sheet, address:'A'+(startRow+i)+':'+col+(startRow+i+sl.length-1), values:sl, driveId, fileId, sessionId }); }
    ops.push({ op:'createTable', sheet:s.sheet, address:'A1:'+col+(Math.max(newN,1)+1), tableName:s.table, driveId, fileId, sessionId });
  } else {
    if (newN>oldN){ let toAdd=newN-oldN; const er=new Array(width).fill(''); while(toAdd>0){ const c=Math.min(toAdd,ADDCH); ops.push({ op:'addRows', table:s.table, values:Array.from({length:c},()=>er.slice()), driveId, fileId, sessionId }); toAdd-=c; } }
    else if (newN<oldN){ ops.push({ op:'deleteRange', sheet:s.sheet, address:'A'+(newN+2)+':'+col+(oldN+1), driveId, fileId, sessionId }); }
    for (let i=0;i<all.length;i+=CH){ const sl=all.slice(i,i+CH);
      ops.push({ op:'write', prop, sheet:s.sheet, address:'A'+(startRow+i)+':'+col+(startRow+i+sl.length-1), values:sl, driveId, fileId, sessionId }); }
  }
}
return ops.map(o=>({json:o}));

const store = $getWorkflowStaticData('global').rt21;
const init = $('Init').first().json;
const fileId = $('Resolve File').first().json.fileId;
const sessionId = $('Create Session').first().json.id;
const driveId = init.driveId;
store.fileId = fileId; store.sessionId = sessionId;
const custMap = store.custMap || {};

const statusByOrder={}, reqDateByOrder={}, custNameByOrder={}, cityByOrder={};
for (const o of store.orders){
  statusByOrder[o.No]=o.Status||'Open';
  reqDateByOrder[o.No]=o.Requested_Delivery_Date||'';
  custNameByOrder[o.No]=o.Sell_to_Customer_Name||'';
  cityByOrder[o.No]=o.Ship_to_City||'';
}
// Invoiced rows are dated by POSTING DATE (shipped & billed), per the dashboard definition.
const postDateByInvoice={}, custNameByInvoice={}, cityByInvoice={};
for (const v of store.invoices){
  postDateByInvoice[v.No]=v.Posting_Date||v.Requested_Delivery_Date_SOD||'';
  custNameByInvoice[v.No]=v.Sell_to_Customer_Name||'';
  cityByInvoice[v.No]=v.Ship_to_City||'';
}

const XL = "=XLOOKUP([@[Sell_to_Customer_No]],Customers!$A$2:$A$133,Customers!$B$2:$B$133)";
const ND = "=[@No]&\" - \"&[@Description]";
const combined=[];
function push(rec){
  const r = combined.length + 2;               // sheet row this record will occupy
  rec['Sell_to_Customer_Name'] = XL;           // formula column J (unchanged)
  rec['Month'] = '=DATE(YEAR(C'+r+'),MONTH(C'+r+'),1)';   // formula column L (unchanged)
  rec['No. Desc'] = ND;                        // formula column O (unchanged)
  combined.push(rec);
}

for (const l of store.orderLines){
  if(l.Type!=='Item') continue;
  const qty=Number(l.Quantity)||0;
  const out=Number(l.Outstanding_Quantity)||0;
  const up=qty>0?Math.round(((Number(l.Line_Amount)||0)/qty)*10000)/10000:'';
  const cust=String(l.Sell_to_Customer_No||'');
  const c=custMap[cust]||{};
  push({ 'SO Number':l.Document_No,
    'Status':statusByOrder[l.Document_No]||'Open',
    'Requested_Delivery_Date':reqDateByOrder[l.Document_No]||l.Shipment_Date||'',
    'No':l.No, 'Description':l.Description,
    'Quantity':out, 'Unit Price':up,
    'Line_Amount': up===''?0:Math.round(up*out*100)/100,
    'Sell_to_Customer_No':cust,
    'Source':'Open Order',
    'Ship_to_City': cityByOrder[l.Document_No] || c.city || '',
    'State': c.state || '' });
}
for (const l of store.invoiceLines){
  if(l.Type!=='Item') continue;
  const cust=String(l.Sell_to_Customer_No||'');
  const c=custMap[cust]||{};
  push({ 'SO Number':l.Order_No||l.Document_No,
    'Status':'Invoiced',
    'Requested_Delivery_Date':postDateByInvoice[l.Document_No]||l.ERC_Posting_Date||'',
    'No':l.No, 'Description':l.Description,
    'Quantity':Number(l.Quantity)||0, 'Unit Price':l.Unit_Price,
    'Line_Amount':l.Amount,
    'Sell_to_Customer_No':cust,
    'Source':'Invoiced',
    'Ship_to_City': cityByInvoice[l.Document_No] || c.city || '',
    'State': c.state || '' });
}
store.combinedCount = combined.length;

const sheets = [
  { sheet:'Sales Orders',  table:'Table1',   rows:store.orders,       cols:["No", "Order_Date", "Requested_Delivery_Date", "Shipment_Date", "Status", "Sell_to_Customer_No", "Sell_to_Customer_Name", "Ship_to_Name", "Ship_to_City", "Shipping_Agent_Code", "External_Document_No", "Salesperson_Code", "Location_Code", "Completely_Shipped"] },
  { sheet:'Order Lines',   table:'Table2',   rows:store.orderLines,   cols:["Document_No", "Line_No", "Type", "No", "Description", "Quantity", "Qty_to_Ship", "Outstanding_Quantity", "Unit_of_Measure_Code", "Line_Amount", "Shipment_Date", "Location_Code", "Sell_to_Customer_No"] },
  { sheet:'Invoices',      table:'Table3',   rows:store.invoices,     cols:["No", "Posting_Date", "Due_Date", "Order_No", "Sell_to_Customer_No", "Sell_to_Customer_Name", "Ship_to_Name", "Ship_to_City", "Shipping_Agent_Code", "External_Document_No", "Salesperson_Code", "Payment_Terms_Code", "Location_Code"] },
  { sheet:'Invoice Lines', table:'Table4',   rows:store.invoiceLines, cols:["Document_No", "Line_No", "Type", "No", "Description", "Quantity", "Unit_of_Measure_Code", "Unit_Price", "Line_Discount_Amount", "Amount", "Amount_Including_VAT", "ERC_Posting_Date", "Sell_to_Customer_No", "Order_No"] },
  // Combined: 15 cols matching the v4 table. Formula columns J/L/O are re-written
  // with their existing formulas so they extend to newly appended rows.
  { sheet:'Combined', table:'Combined', rows:combined, useFormulas:true, skipHeader:true,
    cols:["SO Number", "Status", "Requested_Delivery_Date", "No", "Description", "Quantity", "Unit Price", "Line_Amount", "Sell_to_Customer_No", "Sell_to_Customer_Name", "Source", "Month", "Ship_to_City", "State", "No. Desc"] }
];

store.sheets = sheets;
store.old = {};
return sheets.map(s => ({ json: { sheet: s.sheet, table: s.table, sessionId, driveId, fileId } }));

const item = $('Loop Sheets').first().json;
const resp = $json;
const store = $getWorkflowStaticData('global').rt21;
let oldN = -1;
if (resp && typeof resp.rowCount === 'number') oldN = resp.rowCount - 1;
store.old[item.sheet] = oldN;
return [{ json: { sheet: item.sheet, oldN } }];

const rows = $json.values || [];
const store = $getWorkflowStaticData('global').rt21;
const m = {};
for (const r of rows) {
  const no = String(r[0]==null?'':r[0]).trim();
  if (!no) continue;
  m[no] = { city: r[7]==null?'':String(r[7]), state: r[8]==null?'':String(r[8]) };
}
store.custMap = m;
return [{ json: { customersLoaded: Object.keys(m).length } }];

